["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    type = \"string\",\n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_SUCCESS, UNIT_SPELLCAST_SUCCEEDED",
["names"] = {
},
["check"] = "event",
["spellIds"] = {
},
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.cdWindow,\n            expirationTime = GetTime() + aura_env.cdWindow,\n            type = \"Jasper\",\n        }\n        return true\n    end\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        if extra ~= \"boss1\" and extra ~= \"boss2\" and extra ~= \"boss3\" and extra ~= \"boss4\" then\n            return false\n        end\n        \n        if spellIdS ~= aura_env.cobaltStart and spellIdS ~= aura_env.jadeStart and spellIdS ~= aura_env.jasperStart and spellIdS ~= aura_env.amethystStart then\n            return false\n        end\n        \n        if spellIdS == aura_env.cobaltStart then\n            aura_env.activePetrification = \"Cobalt\"\n            WeakAuras.ScanEvents(\"EMITY_COBALT\")\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                type = \"Cobalt\",\n            }\n        elseif spellIdS == aura_env.jadeStart then\n            aura_env.activePetrification = \"Jade\"\n            WeakAuras.ScanEvents(\"EMITY_JADE\")\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                type = \"Jade\",\n            }\n        elseif spellIdS == aura_env.jasperStart then\n            aura_env.activePetrification = \"Jasper\"\n            WeakAuras.ScanEvents(\"EMITY_JASPER\")\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                type = \"Jasper\",\n            }\n        elseif spellIdS == aura_env.amethystStart then\n            aura_env.activePetrification = \"Amethyst\"\n            WeakAuras.ScanEvents(\"EMITY_AMETHYST\")\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                type = \"Amethyst\",\n            }\n        end\n        return true\n    end\n    \n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if spellId ~= aura_env.cobaltEnd and spellId ~= aura_env.jadeEnd and spellId ~= aura_env.jasperEnd and spellId ~= aura_env.amethystEnd then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            \n            if spellId == aura_env.cobaltEnd then\n                if aura_env.activePetrification == \"Cobalt\" then\n                    aura_env.activePetrification = \"None\"\n                    if allstates[\"\"] then\n                        allstates[\"\"].changed = true\n                        allstates[\"\"].show = false\n                        return true\n                    end\n                end\n                \n            elseif spellId == aura_env.jadeEnd then\n                if aura_env.activePetrification == \"Jade\" then\n                    aura_env.activePetrification = \"None\"\n                    if allstates[\"\"] then\n                        allstates[\"\"].changed = true\n                        allstates[\"\"].show = false\n                        return true\n                    end\n                end\n                \n            elseif spellId == aura_env.jasperEnd then\n                if aura_env.activePetrification == \"Jasper\" then\n                    aura_env.activePetrification = \"None\"\n                    if allstates[\"\"] then\n                        allstates[\"\"].changed = true\n                        allstates[\"\"].show = false\n                        return true\n                    end\n                end\n                \n            elseif spellId == aura_env.amethystEnd then\n                if aura_env.activePetrification == \"Amethyst\" then\n                    aura_env.activePetrification = \"None\"\n                    if allstates[\"\"] then\n                        allstates[\"\"].changed = true\n                        allstates[\"\"].show = false\n                        return true\n                    end\n                end\n            end\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.activePetrification = \"None\"\n        return true\n    end\nend",
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
["custom"] = "function(event, _, subEvent,_,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            \n            if aura_env.spellEnd[spellId] then\n                return true\n            end\n        end\n    end\nend\n\n\n\n",
},
