["custom"] = "function(event,...)\n    local name, _, difficultyID = GetInstanceInfo()\n    if event == \"OPTIONS\" then\n        aura_env.raidName = \"Подземелья Могу'шан\"\n        aura_env.raidType = \"25 Героик\"\n        return true\n    end\n    \n    if name == \"Подземелья Могу'шан\" or name == \"Mogu'shan Vaults\" or name == \"Сердце Страха\" or name == \"Heart of Fear\" or name == \"Терраса Вечной Весны\" or name == \"Terrace of Endless Spring\" then\n        aura_env.raidName = name\n        if difficultyID == 3 then\n            aura_env.raidType = \"10 Нормал\"\n            return true\n        elseif difficultyID == 4 then\n            aura_env.raidType = \"25 Нормал\"\n            return true\n        elseif difficultyID == 5 then\n            aura_env.raidType = \"10 Героик\"\n            return true\n        elseif difficultyID == 6 then\n            aura_env.raidType = \"25 Героик\"\n            return true\n        elseif difficultyID == 17 then\n            aura_env.raidType = \"ЛФР\"\n            return true\n        end\n    end\nend\n\n\n\n\n",
