["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    expirationTime = true,\n    status = \"string\",\n}\n\n\n",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates,event,unit,subEvent,_,sourceGUID,sourceName,_,_,destGUID,_,_,_,spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if subEvent == \"SPELL_INTERRUPT\" then\n            if allstates[destGUID] then\n                allstates[destGUID].duration = 0.75\n                allstates[destGUID].expirationTime = GetTime() + 0.75\n                allstates[destGUID].changed = true\n                allstates[destGUID].status = \"Kicked\"\n                allstates[destGUID].interrupter = sourceName\n                return true\n            end\n        end\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            local npcId = select(6, strsplit(\"-\", sourceGUID))\n            if aura_env.npc[npcId] then\n                aura_env.guids[sourceGUID] = true\n                aura_env.expirationTimes[sourceGUID] = 0.25 + GetTime()\n                for _, plateData in pairs(C_NamePlate.GetNamePlates()) do\n                    local nameplateUnit = plateData.UnitFrame.displayedUnit\n                    if UnitGUID(nameplateUnit) == sourceGUID then\n                        allstates[sourceGUID] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"timed\",\n                            duration = 0.25,\n                            expirationTime = aura_env.expirationTimes[sourceGUID],\n                            unit = nameplateUnit,\n                            autoHide = true,\n                            status = \"Casted\"\n                        }\n                        return true\n                    end\n                end\n            end\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" then\n            local npcId = select(6, strsplit(\"-\", sourceGUID))\n            if aura_env.npc[npcId] then\n                aura_env.guids[sourceGUID] = true\n                aura_env.expirationTimes[sourceGUID] = aura_env.castTime + GetTime()\n                for _, plateData in pairs(C_NamePlate.GetNamePlates()) do\n                    local nameplateUnit = plateData.UnitFrame.displayedUnit\n                    if UnitGUID(nameplateUnit) == sourceGUID then\n                        allstates[sourceGUID] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"timed\",\n                            duration = aura_env.castTime,\n                            expirationTime = aura_env.expirationTimes[sourceGUID],\n                            unit = nameplateUnit,\n                            autoHide = true,\n                            status = \"Casting\"\n                        }\n                        return true\n                    end\n                end\n            end\n        end\n    end\n    \n    if event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local unitGUID = UnitGUID(unit)\n        if allstates[unitGUID] then\n            allstates[unitGUID].show = false\n            allstates[unitGUID].changed = true\n            return true\n        end\n    end\n    \n    if event == \"NAME_PLATE_UNIT_ADDED\" then\n        local unitGUID = UnitGUID(unit)\n        if aura_env.guids[unitGUID] and aura_env.expirationTimes[unitGUID] then\n            local timeLeft = aura_env.expirationTimes[unitGUID] - GetTime()\n            if timeLeft > 0 then\n                allstates[unitGUID] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = timeLeft,\n                    expirationTime = aura_env.expirationTimes[unitGUID],\n                    unit = unit,\n                    autoHide = true,\n                }\n                return true\n            end\n        end\n    end\nend",
