["customText"] = "function()\n    local multi = 60000 -- 25 гер\n    local _, _, difficultyID = GetInstanceInfo()\n    -- 3 = 10 Нормал; 4 = 25 Нормал; 5 = 10 Героик; 6 = 25 Героик; 17 = ЛФР\n    if difficultyID == 3 then\n        multi =  40000\n    elseif difficultyID == 4 then\n        multi = 60000\n    elseif difficultyID == 5 then\n        multi = 40000\n    elseif difficultyID == 17 then\n        multi = 30000\n    end\n    local colorCode = \"|cFFfff468\"\n    \n    if multi * aura_env.state.stacks / 1000 * 1.6 < 1000 then\n        return colorCode .. math.floor(multi * aura_env.state.stacks / 1000 * 1.6) .. \"k/с|r\"\n    else\n        return colorCode .. math.floor(multi * aura_env.state.stacks / 1000) / 1000 * 1.6 .. \"m/с|r\"\n    end\nend",
