["ТВВ Гер - Лут с монетки"] = {
["iconSource"] = -1,
["wagoID"] = "X2r68vxMW",
["parent"] = "Т14 Лут с монетки: Все боссы",
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["url"] = "https://wago.io/X2r68vxMW/64",
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    level = \"string\",\n    desc = \"string\",\n    glow = \"bool\",\n    legenadry = \"bool\"\n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["events"] = "CHAT_MSG_LOOT",
["names"] = {
},
["check"] = "event",
["spellIds"] = {
},
["custom"] = "function(allstates, event, text, extra)\n    \n    if not text then \n        return false\n    end\n    \n    for _,v in pairs(aura_env.config.items) do\n        local finditem = \"Hitem:\"..v.item_id..\":\"\n        local bonusText = \"дополнительную\"\n        if string.find(text, finditem, 1, true) and string.find(text, bonusText, 1, true) then\n            \n            local player, item = aura_env.ExtractBonusLootDetails(text)\n            \n            if not player then\n                return\n            end\n            \n            local CLASS_COLORS = {\n                DEATHKNIGHT = \"C41F3B\",\n                DRUID       = \"FF7D0A\",\n                HUNTER      = \"ABD473\",\n                MAGE        = \"69CCF0\",\n                MONK        = \"00FF96\",\n                PALADIN     = \"F58CBA\",\n                PRIEST      = \"FFFFFF\",\n                ROGUE       = \"FFF569\",\n                SHAMAN      = \"0070DE\",\n                WARLOCK     = \"9482C9\",\n                WARRIOR     = \"C79C6E\",\n            }\n            \n            local class = UnitClassBase(player)\n            if class and CLASS_COLORS[class] then\n                player = \"|cFF\" .. CLASS_COLORS[class] .. Ambiguate(player, \"none\") .. \"|r\"\n            else\n                player = Ambiguate(player, \"none\")\n            end\n            \n            local itemName, _, itemRarity, itemLevel, _, _, itemSubType, _, _, itemIcon = C_Item.GetItemInfo(v.item_id)\n            if itemName == nil then\n                itemName = v.item_name\n            end\n            local legenadryItem = false\n            local description = \"\"\n            local firstItem = true\n            \n            if aura_env.slot[v.slotItem] then\n                description = aura_env.slot[v.slotItem]\n            end\n            \n            if aura_env.armor[itemSubType] then\n                description = description .. \", \" .. aura_env.armor[itemSubType]\n            end\n            \n            if aura_env.boe[v.item_id] then\n                description = description .. \", БоЕ\"\n            end\n            \n            if itemRarity == 5 then \n                legenadryItem = true\n            end\n            \n            if v.slotItem <= 29 then\n                for i = 1, 31 do\n                    local specName = aura_env.spec[i]\n                    local table = v.specBis\n                    if table[specName] then\n                        if firstItem == true then\n                            description = description .. \" - Бис \" .. aura_env.specText[i]\n                            firstItem = false\n                        else\n                            description = description .. \", \" .. aura_env.specText[i]\n                        end\n                    end\n                end\n            end\n            \n            allstates[player] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                expirationTime = GetTime() + 30,\n                duration = 30,\n                name = itemName,\n                icon = itemIcon,\n                autoHide = true,\n                itemId = v.item_id,\n                desc = description,\n                level = itemLevel,\n                glow = v.bisItem,\n                legenadry = legenadryItem,\n                player = player\n            }\n            return true\n        end\n    end\nend",
["debuffType"] = "HELPFUL",
},
