["init"] = {
["custom"] = "aura_env.text = \"ВТОРОЙ БОСС\"\naura_env.msgPhaseTwo = {\n    [\"Вы совершили роковую ошибку!\"] = 0,\n}\naura_env.msgPhaseThree = {\n    [\"Скоро вы поймете, почему мои слуги боятся теней!\"] = 0,\n}\naura_env.msgPhaseFour = {\n    [\"Вы разгневали императора! Я ПРИГОВАРИВАЮ ВАС К СМЕРТИ!\"] = 0,\n}\n\n\n\n",
