["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, extra)\n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        if extra and aura_env.msgPhaseTwo[extra] then\n            aura_env.text = \"ВТОРОЙ БОСС\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\SecondPhase.mp3\", \"Master\")\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseThree[extra] then\n            aura_env.text = \"ТРЕТИЙ БОСС\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\ThirdPhase.mp3\", \"Master\")\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseFour[extra] then\n            aura_env.text = \"ЧЕТВЕРТЫЙ БОСС\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\PhsaeFour.mp3\", \"Master\")\n            return true\n        end\n    end\nend",
