["custom"] = "function(event)\n    if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n        aura_env.antispam = GetTime()\n        if event == \"EMITY_COBALT\" then\n            local icon = \"Interface\\\\Icons\\\\spell_frost_piercing chill\"\n            local iconSetting = \":0:0:0:0:64:64:4:60:4:60\"\n            local textPart = \"Синий активен \"\n            aura_env.text = \"|T\" .. icon .. iconSetting .. \"|t \" .. textPart .. \"|T\" ..  icon .. iconSetting .. \"|t\"\n            return true\n        elseif event == \"EMITY_JADE\" then\n            local icon = \"Interface\\\\Icons\\\\inv_jewelcrafting_gem_07\"\n            local iconSetting = \":0:0:0:0:64:64:4:60:4:60\"\n            local textPart = \"Зеленый активен \"\n            aura_env.text = \"|T\" .. icon .. iconSetting .. \"|t \" .. textPart .. \"|T\" ..  icon .. iconSetting .. \"|t\"\n            return true\n        elseif event == \"EMITY_JASPER\" then\n            local icon = \"Interface\\\\Icons\\\\inv_belt_44b\"\n            local iconSetting = \":0:0:0:0:64:64:4:60:4:60\"\n            local textPart = \"Красный активен \"\n            aura_env.text = \"|T\" .. icon .. iconSetting .. \"|t \" .. textPart .. \"|T\" ..  icon .. iconSetting .. \"|t\"\n            return true\n        elseif event == \"EMITY_AMETHYST\" then\n            local icon = \"Interface\\\\Icons\\\\spell_yorsahj_bloodboil_purple\"\n            local iconSetting = \":0:0:0:0:64:64:4:60:4:60\"\n            local textPart = \"Фиолетовый активен \"\n            aura_env.text = \"|T\" .. icon .. iconSetting .. \"|t \" .. textPart .. \"|T\" ..  icon .. iconSetting .. \"|t\"\n            return true\n        end\n    end\nend\n\n\n",
