["custom"] = "function(allstates, event, extra, subEvent,_,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" then\n            aura_env.text = \"ФАЗА 3\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 3,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\ThirdPhase.mp3\", \"Master\")\n            return true\n        end\n        \n    end\n    \n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        if extra and aura_env.msgPhaseOne[extra] then\n            aura_env.text = \"ФАЗА 1\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 10,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\FirstPhase.mp3\", \"Master\")\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseTwo[extra] then\n            aura_env.text = \"ФАЗА 2\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 3,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\SecondPhase.mp3\", \"Master\")\n            return true\n        end\n    end\nend",
