["custom"] = "function(a, e, ...)\n    \n    if e == \"OPTIONS\" then\n        local startPercent = 70\n        local endPercent = 66\n        local value = 3\n        local total = startPercent - endPercent\n        \n        a[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = math.random(1,4),\n            total = 4,\n            startPercent = startPercent,\n            endPercent = endPercent,\n        }\n        return true\n    end\n    \n    if e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _,subEvent,_,sourceGUID,_,_,_,destGUID,_,_,_,spellId = ...\n        \n        if spellId ~= aura_env.getAway then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" then\n            print(spellId)\n            local unit = \"boss1\"\n            local hp = UnitHealth(unit)\n            local maxhp = UnitHealthMax(unit)\n            if maxhp and maxhp > 0 then\n                print(\"не мертв\")\n                local startPercent = (hp / maxhp) * 100\n                local fourPercent = maxhp * 0.04\n                aura_env.allow = true\n                local endPercent = startPercent - ((fourPercent / UnitHealthMax(\"boss1\")) * 100)\n                aura_env.getAwayStartPercent = startPercent\n                aura_env.getAwayEndPercent = endPercent\n                print(\"провел подсчет\")\n                a[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"static\",\n                    value = 0,\n                    total = startPercent - endPercent,\n                    startPercent = startPercent,\n                    endPercent = endPercent,\n                }\n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_REMOVED\" then\n            aura_env.allow = false\n            if a[\"\"] then\n                a[\"\"].show = false\n                a[\"\"].changed = true\n                return true\n            end\n        end\n    end\n    \n    if e == \"UNIT_HEALTH\" then\n        if not aura_env.allow then\n            return false\n        end\n        \n        local unit = ...\n        if unit ~= \"boss1\" then \n            return false \n        end\n        \n        local current = UnitHealth(\"boss1\")\n        local max = UnitHealthMax(\"boss1\")\n        if max == 0 then \n            return false \n        end\n        \n        local currentPercent = (current / max) * 100\n        local value = aura_env.getAwayStartPercent - currentPercent\n        local total = aura_env.getAwayStartPercent - aura_env.getAwayEndPercent\n        \n        value = math.max(0, math.min(value, total))\n        \n        a[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = value,\n            total = total,\n            startPercent = aura_env.getAwayStartPercent,\n            endPercent = aura_env.getAwayEndPercent,\n        }\n        return true\n    end\n    \n    if e == \"ENCOUNTER_START\" then\n        aura_env.allow = false\n    end\nend",
