["customVariables"] = "{\n    stacks = true,\n}",
["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates,event, msg)\n    \n    if event == \"OPTIONS\" then\n        aura_env.textNames = WA_ClassColorName(\"player\") .. \", \" .. WA_ClassColorName(\"player\") .. \", \" .. WA_ClassColorName(\"player\")\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            icon = \"Interface\\\\AddOns\\\\EmityCore\\\\icon\\\\clown.tga\",\n        }\n        return true \n    end\n    \n    if event == \"CHAT_MSG_MONSTER_EMOTE\" then\n        \n        if msg and msg:find(aura_env.msgTextHe) then\n            \n            local name = msg:match(\"^(.-)%s*\" .. aura_env.msgTextHe)\n            name = name and strtrim(name) or \"Неизвестно\"\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 4 then\n                aura_env.antispam = GetTime()\n                aura_env.textNames = WA_ClassColorName(name)\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = 3.5,\n                    expirationTime = GetTime() + 5.5,\n                    progressType = \"timed\",\n                    autoHide = true,\n                    icon = \"Interface\\\\AddOns\\\\EmityCore\\\\icon\\\\clown.tga\",\n                }\n                return true \n            else\n                aura_env.textNames = aura_env.textNames .. \", \" .. WA_ClassColorName(name)\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = 3.5,\n                    expirationTime = GetTime() + 5.5,\n                    progressType = \"timed\",\n                    autoHide = true,\n                    icon = \"Interface\\\\AddOns\\\\EmityCore\\\\icon\\\\clown.tga\",\n                }\n                return true \n            end\n        end\n        \n        \n        if msg and msg:find(aura_env.msgTextShe) then\n            \n            local name = msg:match(\"^(.-)%s*\" .. aura_env.msgTextShe)\n            name = name and strtrim(name) or \"Неизвестно\"\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 4 then\n                aura_env.antispam = GetTime()\n                aura_env.textNames = WA_ClassColorName(name)\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = 3.5,\n                    expirationTime = GetTime() + 5.5,\n                    progressType = \"timed\",\n                    autoHide = true,\n                    icon = \"Interface\\\\AddOns\\\\EmityCore\\\\icon\\\\clown.tga\",\n                }\n                return true \n            else\n                aura_env.textNames = aura_env.textNames .. \", \" .. WA_ClassColorName(name)\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = 3.5,\n                    expirationTime = GetTime() + 5.5,\n                    progressType = \"timed\",\n                    autoHide = true,\n                    icon = \"Interface\\\\AddOns\\\\EmityCore\\\\icon\\\\clown.tga\",\n                }\n                return true \n            end\n        end\n    end\nend",
