["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    expirationTime = true,\n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["events"] = "ENCOUNTER_START, CLEU:SPELL_AURA_REMOVED, CLEU:SPELL_AURA_APPLIED, CLEU:SPELL_CAST_SUCCESS",
["names"] = {
},
["check"] = "event",
["spellIds"] = {
},
["custom"] = "function(allstates, event, extra, subEvent, spellIdS, sourceGUID,_,_,_, destGUID,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] and not aura_env.spellIn[spellId] and not aura_env.spellOut[spellId] and not aura_env.spellBuff[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spell[spellId] then\n            local npcID = select(6, strsplit(\"-\", sourceGUID))\n            if aura_env.NPCs[npcID] then\n                if aura_env.onPlatform == true then\n                    if aura_env.mobActive == true then\n                        aura_env.count = aura_env.count + 1\n                        if aura_env.count == 4 then\n                            aura_env.text = \"СТОЙ В ЦЕНТРЕ\"\n                            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\StayCenter.mp3\", \"Master\")\n                            WeakAuras.ScanEvents(\"EMITY_SHA_RIGHT_CENTER\")\n                            allstates[\"\"] = {\n                                show = true,\n                                changed = true,\n                                duration = 5.5,\n                                expirationTime = GetTime() + 5.5,\n                                progressType = \"timed\",\n                            }\n                            return true\n                        end\n                    end\n                end\n            end\n        end\n        \n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and aura_env.spellBuff[spellId] then\n            local npcID = select(6, strsplit(\"-\", destGUID))\n            if aura_env.NPCs[npcID] then\n                if aura_env.onPlatform == true then\n                    if aura_env.mobActive == true then\n                        aura_env.count = 0\n                        aura_env.text = \"СТОЙ СЛЕВА\"\n                        aura_env.icon = \"Interface\\\\Icons\\\\misc_arrowleft\"\n                        PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\Left.mp3\", \"Master\")\n                        WeakAuras.ScanEvents(\"EMITY_SHA_RIGHT_LEFT\")\n                        allstates[\"\"] = {\n                            show = true,\n                            changed = true,\n                            duration = 28,\n                            expirationTime = GetTime() + 28,\n                            progressType = \"timed\",\n                        }\n                        return true\n                    end\n                end\n            end\n        end\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and aura_env.spellIn[spellId] then\n            if destGUID ~= WeakAuras.myGUID then\n                return false\n            end\n            aura_env.onPlatform = true\n            aura_env.count = 0\n            aura_env.text = \"СТОЙ СЛЕВА\"\n            aura_env.icon = \"Interface\\\\Icons\\\\misc_arrowleft\"\n            WeakAuras.ScanEvents(\"EMITY_SHA_RIGHT_LEFT\")\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = 11,\n                expirationTime = GetTime() + 11,\n                progressType = \"timed\",\n            }\n            return true\n        end\n        \n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and aura_env.spellBuff[spellId] then\n            local npcID = select(6, strsplit(\"-\", destGUID))\n            if aura_env.NPCs[npcID] then\n                aura_env.count = 0\n                aura_env.text = \"СТОЙ СЛЕВА\"\n                aura_env.icon = \"Interface\\\\Icons\\\\misc_arrowleft\"\n                WeakAuras.ScanEvents(\"EMITY_SHA_RIGHT_LEFT\")\n                return true\n            end\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and aura_env.spellOut[spellId] then\n            if destGUID ~= WeakAuras.myGUID then\n                return false\n            end\n            aura_env.onPlatform = false\n            aura_env.count = 0\n            aura_env.text = \"СТОЙ СЛЕВА\"\n            aura_env.icon = \"Interface\\\\Icons\\\\misc_arrowleft\"\n            WeakAuras.ScanEvents(\"EMITY_SHA_RIGHT_OFF\")\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.onPlatform = false\n        aura_env.text = \"СТОЙ СЛЕВА\"\n        aura_env.icon = \"Interface\\\\Icons\\\\misc_arrowleft\"\n        return true\n    end\nend\n\n\n\n",
