["parent"] = "Т14 Тексты: Все боссы",
["preferToUpdate"] = false,
["customText"] = "function()\n    local roleText = aura_env.role\n    local colorCode = \"|cFFFFFFFF\"\n    \n    if aura_env.role == \"DAMAGER\" then\n        roleText = \"ДД\"\n        colorCode = \"|cFF4dff5d\"\n    elseif aura_env.role == \"HEALER\" then\n        roleText = \"Хилл\"\n        colorCode = \"|cFF4dff5d\"\n    elseif aura_env.role == \"TANKER\" or aura_env.role == \"TANK\" then\n        roleText = \"Танк\"\n        colorCode = \"|cFF4dff5d\"\n    end\n    \n    return colorCode .. roleText .. \"|r\"\nend",
