["custom"] = "if aura_env.state and aura_env.state.unit then\n    local priority = {8, 7, 3}\n    for _, mark in ipairs(priority) do\n        if aura_env.marks[mark] then\n            SetRaidTarget(aura_env.state.unit, mark)\n            aura_env.marks[mark] = false\n            break\n        end\n    end\nend",
