["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            icon = 132381,\n            count = math.random(1,3)\n        }\n        return true \n    end\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        if not aura_env.spellPhase[spellIdS] and not aura_env.spell[spellIdS] then\n            return false\n        end\n        \n        if aura_env.spell[spellIdS] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n                aura_env.antispam = GetTime()\n                aura_env.count = aura_env.count + 1\n                aura_env.ScheduleWarning(aura_env.cdWindow)\n                if allstates[\"\"] then\n                    allstates[\"\"].show = false\n                    allstates[\"\"].changed = true\n                    return true\n                end\n            end\n        end\n        \n        if aura_env.spellPhase[spellIdS] then\n            if extra ~= \"boss1\" and extra ~= \"boss2\" and extra ~= \"boss3\" then\n                return false\n            end\n            \n            local guid = UnitGUID(extra)\n            local npcId = select(6, strsplit(\"-\", guid))\n            \n            if npcId == \"60710\" then -- Subetai\n                aura_env.phase = false\n                if allstates[\"\"] then\n                    allstates[\"\"].show = false\n                    allstates[\"\"].changed = true\n                    return true\n                end\n            end\n        end\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id and aura_env.phase == true then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = 5,\n                expirationTime = GetTime() + 5,\n                progressType = \"timed\",\n                icon = 132381,\n                count = aura_env.count,\n            }\n            return true\n        end\n    end\n    \n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        if extra and aura_env.msgPhase[extra] then\n            aura_env.phase = true\n            aura_env.count = 1\n            aura_env.ScheduleWarning(aura_env.cdStart)\n            return true\n        end\n    end\nend\n\n\n",
