["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.phaseTwo == false then\n            aura_env.count = aura_env.count + 1\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                progressType = \"timed\"\n            }\n            return true\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.phaseTwo == true then\n            aura_env.count = aura_env.count + 1\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindowAfterPhase,\n                expirationTime = GetTime() + aura_env.cdWindowAfterPhase,\n                progressType = \"timed\"\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.phaseCount = 1\n        aura_env.phaseTwo = false\n        aura_env.count = 1\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart,\n            expirationTime = GetTime() + aura_env.cdStart,\n            progressType = \"timed\"\n        }\n        return true\n    end\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        if not aura_env.spellPhase[spellIdS] then\n            return false\n        end\n        \n        if aura_env.phaseCount == 1 then\n            aura_env.phaseCount = aura_env.phaseCount + 1\n            aura_env.phaseTwo = true\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdStartAfterPhase,\n                expirationTime = GetTime() + aura_env.cdStartAfterPhase,\n                progressType = \"timed\"\n            }\n            return true\n        end\n    end\n    \nend",
