["duration"] = "20",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, ...)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _,subEvent,_,sourceGUID,_,_,_,destGUID,_,_,_,spellId = ...\n        \n        if subEvent == \"UNIT_DIED\" then\n            if allstates[destGUID] then\n                allstates[destGUID].show = false\n                allstates[destGUID].changed = true\n                aura_env.guidData[destGUID] = nil\n                return true\n            end\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" then\n            if spellId ~= 122193 then\n                return false\n            end\n            \n            local expirationTime = 36 + GetTime()\n            aura_env.guidData[sourceGUID] = expirationTime\n            for _, plateData in pairs(C_NamePlate.GetNamePlates()) do\n                local nameplateUnit = plateData.UnitFrame.displayedUnit\n                if UnitGUID(nameplateUnit) == sourceGUID then\n                    allstates[sourceGUID] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        duration = 36,\n                        expirationTime = expirationTime,\n                        unit = nameplateUnit,\n                    }\n                    return true\n                end\n            end\n        end\n        return true\n    end\n    \n    if event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local unit = ...\n        local guid = UnitGUID(unit)\n        if allstates[guid] then\n            allstates[guid].show = false\n            allstates[guid].changed = true\n            return true\n        end\n    end\n    \n    if event == \"NAME_PLATE_UNIT_ADDED\" then\n        local unit = ...\n        local guid = UnitGUID(unit)\n        local expirationTime = aura_env.guidData[guid]\n        if expirationTime and (expirationTime - GetTime() > 0) then\n            allstates[guid] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = expirationTime - GetTime(),\n                expirationTime = expirationTime,\n                unit = unit,\n            }\n            return true\n        end\n    end\n    return false\nend",
