["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if (subEvent == \"SPELL_AURA_APPLIED\" and aura_env.count == 1) or subEvent == \"SPELL_AURA_APPLIED_DOSE\" then\n            aura_env.count = aura_env.count + 1\n            if aura_env.phaseTwo == false then\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.cdWindow,\n                    expirationTime = GetTime() + aura_env.cdWindow,\n                    progressType = \"timed\",\n                }\n                return true\n            else\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.cdWindowPhase,\n                    expirationTime = GetTime() + aura_env.cdWindowPhase,\n                    progressType = \"timed\",\n                }\n                return true\n            end\n        end\n    end\n    \n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        if extra and extra == aura_env.msgText then\n            aura_env.phaseTwo = true\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdAfterPhase,\n                expirationTime = GetTime() + aura_env.cdAfterPhase,\n                progressType = \"timed\",\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.phaseTwo = false\n        aura_env.count = 1\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart,\n            expirationTime = GetTime() + aura_env.cdStart,\n            progressType = \"timed\",\n        }\n        return true\n    end\nend",
