},
["custom"] = "function(allstates, event, extra, subEvent, spellIdS, sourceGUID,_,_,_, destGUID,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if subEvent == \"UNIT_DIED\" then\n            \n            local npcID = select(6, strsplit(\"-\", destGUID))\n            if aura_env.NPCs[npcID] then\n                if allstates[destGUID] then\n                    allstates[destGUID] = {\n                        show = false,\n                        changed = true,\n                    }\n                    return true\n                end\n            end\n        end\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" then\n            local npcID = select(6, strsplit(\"-\", sourceGUID))\n            if npcID == \"62980\" then\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"precast\",\n                    sourceUnit = \"БОСС\",\n                }\n                return true\n            else\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"precast\",\n                    sourceUnit = \"КОПИЯ\",\n                }\n                return true\n            end\n        end\n    end\nend",
