["СС: Дисплей Ун'сок - Ваятель жизни Бэкенд"] = {
["outline"] = "OUTLINE",
["wagoID"] = "X2r68vxMW",
["authorOptions"] = {
},
["displayText"] = "",
["customText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/X2r68vxMW/64",
["actions"] = {
["start"] = {
},
["init"] = {
["do_custom_load"] = false,
["custom"] = "aura_env.key = \"UNSOK_AMBER_EXPLOSION_CONSTRUCT\"\naura_env.counts = {}\naura_env.constructCastCount = 1\naura_env.cdStart = 12.8\naura_env.cdWindow = 12.8\naura_env.cdWindowConstruct = 18\naura_env.breakFree = 123060\naura_env.reshape = 122370\naura_env.explosion = 122398\naura_env.npcID = \"62701\" -- Construct\naura_env.npcIDMonstrosity = \"62711\" -- Monstrosity\naura_env.maxSlots = 10\n\naura_env.constructSlots = {}\naura_env.constructGUIDs = {}\n\nfunction aura_env.getFreeSlot()\n    for i = 1, aura_env.maxSlots do\n        if not aura_env.constructSlots[i] then\n            return i\n        end\n    end\n    return nil\nend\n\nfunction aura_env.assignSlot(guid)\n    local slot = aura_env.getFreeSlot()\n    if not slot then return end\n    aura_env.constructSlots[slot] = guid\n    aura_env.constructGUIDs[guid] = slot\n    return slot\nend\n\nfunction aura_env.freeSlot(guid)\n    local slot = aura_env.constructGUIDs[guid]\n    if slot then\n        aura_env.constructSlots[slot] = nil\n        aura_env.constructGUIDs[guid] = nil\n    end\n    return slot\nend\n\nfunction aura_env.getSlot(guid)\n    return aura_env.constructGUIDs[guid]\nend\n\nfunction aura_env.nuTimer(key, countdown, count, guid, name)\n    WeakAuras.ScanEvents(\"WA_EMITY_TIMER\", key, countdown, count, guid, name)\nend\n\nfunction aura_env.updateState(allstates)\n    allstates[\"\"] = {\n        show = true,\n        changed = true,\n    }\nend\n\nfunction aura_env.hideState(allstates)\n    if allstates[\"\"] then\n        allstates[\"\"].show = false\n        allstates[\"\"].changed = true\n        return true\n    end\nend\n\nfunction aura_env.preWarn(key, duration, preWarnTime, count)\n    if not preWarnTime then\n        preWarnTime = 3\n    end\n    \n    if aura_env.preWarnTimer then\n        aura_env.preWarnTimer:Cancel()\n        aura_env.preWarnTimer = nil\n    end\n    aura_env.preWarnTimer = C_Timer.NewTimer(duration - preWarnTime, function()\n            WeakAuras.ScanEvents(\"WA_\" .. key ..\"_PREWARN\", preWarnTime, count)\n            aura_env.preWarnTimer = nil\n    end)\nend\n\nfunction aura_env.preWarnCancel(key)\n    WeakAuras.ScanEvents(\"WA_\" .. key .. \"_PREWARN_CANCEL\")\n    if aura_env.preWarnTimer then\n        aura_env.preWarnTimer:Cancel()\n        aura_env.preWarnTimer = nil\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "aura_env.counts = {}\naura_env.constructCastCount = 1\naura_env.constructSlots = {}\naura_env.constructGUIDs = {}\naura_env.nuTimer(nil)",
["do_sound"] = false,
["sound"] = "Interface\\Addons\\WeakAuras\\PowerAurasMedia\\Sounds\\aggro.ogg",
["do_message"] = false,
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates,event,_,subEvent,_,sourceGUID,sourceName,_,_,destGUID,destName,_,_,spellId,_,_,extraSpellId)\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.counts = {}\n        aura_env.constructCastCount = 1\n        aura_env.constructSlots = {}\n        aura_env.constructGUIDs = {}\n        aura_env.updateState(allstates)\n        return true\n    end\n    \n    if subEvent == \"UNIT_DIED\" then\n        local npcID = select(6, strsplit(\"-\", destGUID))\n        if npcID == aura_env.npcID then\n            WeakAuras.ScanEvents(\"WA_EMITY_TIMER\", aura_env.key, nil, nil, destGUID)\n            return true\n        end\n    end\n    \n    if spellId ~= aura_env.reshape and spellId ~= aura_env.explosion and spellId ~= aura_env.breakFree then\n        return false\n    end\n    \n    if subEvent == \"SPELL_INTERRUPT\" then\n        local npcID = select(6, strsplit(\"-\", destGUID))\n        \n        if npcID == aura_env.npcIDMonstrosity then\n            WeakAuras.ScanEvents(\"WA_UNSOK_AMBER_EXPLOSION_INTERRUPT\", sourceGUID, destGUID)\n        else\n            WeakAuras.ScanEvents(\"WA_UNSOK_AMBER_EXPLOSION_PLAYER_INTERRUPT\", WeakAuras.myGUID)\n        end\n    end\n    \n    if subEvent == \"SPELL_AURA_APPLIED\" then\n        if spellId == aura_env.reshape then\n            local slot = aura_env.assignSlot(destGUID)\n            \n            if slot then\n                local key = \"UNSOK_AMBER_EXPLOSION_PLAYER_\" .. slot\n                aura_env.counts[destGUID] = 1\n                aura_env.nuTimer(key, aura_env.cdStart, aura_env.counts[destGUID], destGUID, destName)\n                if destGUID == WeakAuras.myGUID then\n                    C_Timer.After(3, function()\n                            WeakAuras.ScanEvents(\"WA_UNSOK_NAMEPLATE_HIDE\")\n                    end)\n                    aura_env.preWarn(\"UNSOK_AMBER_EXPLOSION_PLAYER\", aura_env.cdStart, 5, aura_env.counts[destGUID])\n                end\n                return true\n            end\n        end\n    elseif subEvent == \"SPELL_AURA_REMOVED\" then\n        if spellId == aura_env.reshape then\n            local slot = aura_env.freeSlot(destGUID)\n            \n            if slot then\n                local key = \"UNSOK_AMBER_EXPLOSION_PLAYER_\" .. slot\n                aura_env.nuTimer(key, nil, nil, destGUID, destName)\n                if destGUID == WeakAuras.myGUID then\n                    aura_env.preWarnCancel(\"UNSOK_AMBER_EXPLOSION_PLAYER\") \n                end\n                return true\n            end\n        end\n    end\n    \n    if subEvent == \"SPELL_CAST_START\" then\n        if spellId == aura_env.explosion then\n            local npcID = select(6, strsplit(\"-\", sourceGUID))\n            \n            if npcID == aura_env.npcID then\n                aura_env.nuTimer(aura_env.key, 0, aura_env.constructCastCount, sourceGUID)\n                aura_env.constructCastCount = aura_env.constructCastCount + 1\n                aura_env.nuTimer(aura_env.key, aura_env.cdWindowConstruct, aura_env.constructCastCount, sourceGUID)\n                return true\n            else\n                local slot = aura_env.getSlot(sourceGUID)\n                if slot then\n                    local key = \"UNSOK_AMBER_EXPLOSION_PLAYER_\" .. slot\n                    local count = aura_env.counts[sourceGUID] or 1\n                    aura_env.nuTimer(key, 0, count, sourceGUID, sourceName)\n                    aura_env.counts[sourceGUID] = count + 1\n                    aura_env.nuTimer(key, aura_env.cdWindow, aura_env.counts[sourceGUID], sourceGUID, sourceName)\n                    if sourceGUID == WeakAuras.myGUID then\n                        WeakAuras.ScanEvents(\"WA_UNSOK_AMBER_EXPLOSION_PLAYER_CAST\", sourceGUID)\n                        aura_env.preWarn(\"UNSOK_AMBER_EXPLOSION_PLAYER\", aura_env.cdWindow, 5, aura_env.counts[sourceGUID])\n                    end\n                    return true\n                end\n            end\n        end\n    end\nend",
["spellIds"] = {
},
