},
["init"] = {
["custom"] = "aura_env.spellPrecast = {\n    [122713] = 0,\n}\naura_env.spell = {\n    [122713] = 0,\n}\naura_env.spellLastPhase = {\n    [124018] = 0,\n}\naura_env.NPCs = {\n    [\"65174\"] = true,\n}\naura_env.count = 1\naura_env.precastTime = 2\naura_env.castTime = 10",
