{
["trigger"] = {
["type"] = "custom",
["custom_hide"] = "timed",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    status = \"string\",\n    expirationTime = true,\n    sourceUnit = \"string\",\n}",
["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS, sourceGUID,_,_,_, destGUID,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if subEvent == \"UNIT_DIED\" then\n            \n            local npcID = select(6, strsplit(\"-\", destGUID))\n            if aura_env.NPCs[npcID] then\n                if allstates[destGUID] then\n                    allstates[destGUID] = {\n                        show = false,\n                        changed = true,\n                    }\n                    return true\n                end\n            end\n        end\n        \n        if not aura_env.spell[spellId] and not aura_env.spellPrecast[spellId] and not aura_env.spellLastPhase[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spellLastPhase[spellId] then\n            aura_env.count = 1\n            return true\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spellPrecast[spellId] then\n            local npcID = select(6, strsplit(\"-\", sourceGUID))\n            if npcID == \"62980\" then\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = false,\n                    duration = aura_env.precastTime,\n                    expirationTime = GetTime() + aura_env.precastTime,\n                    progressType = \"timed\",\n                    status = \"precast\",\n                    sourceUnit = \"БОСС\",\n                }\n                return true\n            else\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = false,\n                    duration = aura_env.precastTime,\n                    expirationTime = GetTime() + aura_env.precastTime,\n                    progressType = \"timed\",\n                    status = \"precast\",\n                    sourceUnit = \"КОПИЯ\",\n                }\n                return true\n            end\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spell[spellId] then\n            local npcID = select(6, strsplit(\"-\", sourceGUID))\n            if npcID == \"62980\" then\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"cast\",\n                    sourceUnit = \"БОСС\",\n                }\n                return true\n            else\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"cast\",\n                    sourceUnit = \"КОПИЯ\",\n                }\n                return true\n            end\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 1\n        return true\n    end\nend",
