["init"] = {
["custom"] = "local locale = GetLocale()\nif locale == \"ruRU\" then\n    aura_env.armor = {\n        [\"Латы\"] = \"Латы\",\n        [\"Кольчуга\"] = \"Кольчуга\",\n        [\"Кожа\"] = \"Кожа\",\n        [\"Ткань\"] = \"Ткань\",\n    }\nelse\n    aura_env.armor = {\n        [\"Plate\"] = \"Латы\",\n        [\"Mail\"] = \"Кольчуга\",\n        [\"Leather\"] = \"Кожа\",\n        [\"Cloth\"] = \"Ткань\",\n    }\nend\n\naura_env.slot = {\n    [1] = \"Голова\",\n    [2] = \"Шея\",\n    [3] = \"Плечи\",\n    [4] = \"Плащ\",\n    [5] = \"Грудь\",\n    [6] = \"Наручи\",\n    [7] = \"Перчатки\",\n    [8] = \"Пояс\",\n    [9] = \"Ноги\",\n    [10] = \"Ступни\",\n    [11] = \"Кольцо\",\n    [12] = \"Тринька\",\n    [13] = \"Ружье\",\n    [14] = \"Лук\",\n    [15] = \"Посох\",\n    [16] = \"Меч, Двуручный\",\n    [17] = \"Меч, Одноручный\",\n    [18] = \"Дробящее, Двуручное\",\n    [19] = \"Дробящее, Одноручное\",\n    [20] = \"Топор, Двуручный\",\n    [21] = \"Топор, Одноручный\",\n    [22] = \"Кистевое\",\n    [23] = \"Кинжал\",\n    [24] = \"Левая рука\",\n    [25] = \"Щит\",\n    [26] = \"Метательное\",\n    [27] = \"Арбалет\",\n    [28] = \"Древковое\",\n    [29] = \"Жезл\",\n    [30] = \"Маунт\",\n    [31] = \"Токен, Ноги - |cfff58cbaПал|r, |cfff0ebe0Прист|r, |cff9382c9Лок|r\",\n    [32] = \"Токен, Ноги - |cffc69b6dВар|r, |cffaad372Хант|r, |cff2359ffШам|r, |cff00FF98Монк|r\",\n    [33] = \"Токен, Ноги - |cfffff468Рога|r, |cffc41e3bДК|r, |cff68ccefМаг|r, |cffff7c0aДруид|r\",\n    [34] = \"Токен, Перчатки - |cfff58cbaПал|r, |cfff0ebe0Прист|r, |cff9382c9Лок|r\",\n    [35] = \"Токен, Перчатки - |cffc69b6dВар|r, |cffaad372Хант|r, |cff2359ffШам|, |cff00FF98Монк|rr\",\n    [36] = \"Токен, Перчатки - |cfffff468Рога|r, |cffc41e3bДК|r, |cff68ccefМаг|r, |cffff7c0aДруид|r\",\n    [37] = \"Токен, Плечи - |cfff58cbaПал|r, |cfff0ebe0Прист|r, |cff9382c9Лок|r\",\n    [38] = \"Токен, Плечи - |cffc69b6dВар|r, |cffaad372Хант|r, |cff2359ffШам|r, |cff00FF98Монк|r\",\n    [39] = \"Токен, Плечи - |cfffff468Рога|r, |cffc41e3bДК|r, |cff68ccefМаг|r, |cffff7c0aДруид|r\",\n    [40] = \"Токен, Грудь - |cfff58cbaПал|r, |cfff0ebe0Прист|r, |cff9382c9Лок|r\",\n    [41] = \"Токен, Грудь - |cffc69b6dВар|r, |cffaad372Хант|r, |cff2359ffШам|r, |cff00FF98Монк|r\",\n    [42] = \"Токен, Грудь - |cfffff468Рога|r, |cffc41e3bДК|r, |cff68ccefМаг|r, |cffff7c0aДруид|r\",\n    [43] = \"Токен, Голова - |cfff58cbaПал|r, |cfff0ebe0Прист|r, |cff9382c9Лок|r\",\n    [44] = \"Токен, Голова - |cffc69b6dВар|r, |cffaad372Хант|r, |cff2359ffШам|r, |cff00FF98Монк|r\",\n    [45] = \"Токен, Голова - |cfffff468Рога|r, |cffc41e3bДК|r, |cff68ccefМаг|r, |cffff7c0aДруид|r\",\n}\n\naura_env.spec = {\n    [1] = \"blood\",\n    [2] = \"bear\",\n    [3] = \"protPal\",\n    [4] = \"protWar\",\n    [5] = \"brm\",\n    [6] = \"holyPal\",\n    [7] = \"restorSham\",\n    [8] = \"restorDru\",\n    [9] = \"dc\",\n    [10] = \"holyPriest\",\n    [11] = \"mw\",\n    [12] = \"unholy\",\n    [13] = \"frostDK\",\n    [14] = \"arms\",\n    [15] = \"fury\",\n    [16] = \"retri\",\n    [17] = \"surv\",\n    [18] = \"mm\",\n    [19] = \"bm\",\n    [20] = \"enh\",\n    [21] = \"combat\",\n    [22] = \"muti\",\n    [23] = \"sub\",\n    [24] = \"cat\",\n    [25] = \"ww\",\n    [26] = \"elem\",\n    [27] = \"balance\",\n    [28] = \"fire\",\n    [29] = \"arcan\",\n    [30] = \"frostMage\",\n    [31] = \"afli\",\n    [32] = \"demon\",\n    [33] = \"destro\",\n    [34] = \"shadow\",\n}\n\naura_env.specText = {\n    [1] = \"|cffc41e3bБлад|r\",\n    [2] = \"|cffff7c0aМедведь|r\",\n    [3] = \"|cfff58cbaПрот|r\",\n    [4] = \"|cffc69b6dПрот|r\",\n    [5] = \"|cff00FF98БРМ|r\",\n    [6] = \"|cfff58cbaХоли|r\",\n    [7] = \"|cff2359ffРестор|r\",\n    [8] = \"|cffff7c0aРестор|r\",\n    [9] = \"|cfff0ebe0ДЦ|r\",\n    [10] = \"|cfff0ebe0Холи|r\",\n    [11] = \"|cff00FF98МВ|r\",\n    [12] = \"|cffc41e3bАнхоли|r\",\n    [13] = \"|cffc41e3bФрост|r\",\n    [14] = \"|cffc69b6dАрмс|r\",\n    [15] = \"|cffc69b6dФури|r\",\n    [16] = \"|cfff58cbaРетри|r\",\n    [17] = \"|cffaad372Сурв|r\",\n    [18] = \"|cffaad372ММ|r\",\n    [19] = \"|cffaad372БМ|r\",\n    [20] = \"|cff2359ffЭнх|r\",\n    [21] = \"|cfffff468Комбат|r\",\n    [22] = \"|cfffff468Мути|r\",\n    [23] = \"|cfffff468Саб|r\",\n    [24] = \"|cffff7c0aКот|r\",\n    [25] = \"|cff00FF98ВВ|r\",\n    [26] = \"|cff2359ffЭлем|r\",\n    [27] = \"|cffff7c0aСова|r\",\n    [28] = \"|cff68ccefФаер|r\",\n    [29] = \"|cff68ccefАркан|r\",\n    [30] = \"|cff68ccefФрост|r\",\n    [31] = \"|cff9382c9Афли|r\",\n    [32] = \"|cff9382c9Демон|r\",\n    [33] = \"|cff9382c9Дестр|r\",\n    [34] = \"|cfff0ebe0ШП|r\",\n}\n\naura_env.boe = {\n    [86850] = 0,\n    [86844] = 0,\n    [86841] = 0,\n    [86845] = 0,\n    [86843] = 0,\n    [86847] = 0,\n    [86842] = 0,\n    [86846] = 0,\n    [86849] = 0,\n    [86848] = 0,\n    [86192] = 0,\n    [86186] = 0,\n    [86183] = 0,\n    [86187] = 0,\n    [86185] = 0,\n    [86189] = 0,\n    [86184] = 0,\n    [86188] = 0,\n    [86191] = 0,\n    [86190] = 0,\n}\n\naura_env.ExtractBonusLootDetails = function(msg)\n    if not msg then return nil end\n    \n    local selfPattern = string.gsub(LOOT_ITEM_BONUS_ROLL_SELF, \"%%s\", \"(.+)\")\n    local match = string.match(msg, selfPattern)\n    if match then\n        return UnitName(\"player\"), match\n    end\n    \n    local pattern = string.gsub(LOOT_ITEM_BONUS_ROLL, \"%%s\", \"(.+)\", 1)\n    pattern = string.gsub(pattern, \"%%s\", \"(.+)\")\n    local name, item = string.match(msg, pattern)\n    return name, item\nend",
