},
["fixedWidth"] = 200,
["outline"] = "OUTLINE",
["sparkOffsetX"] = 0,
["wagoID"] = "X2r68vxMW",
["color"] = {
0,
1,
0.51372549019608,
1,
},
["adjustedMin"] = "",
["shadowYOffset"] = -1,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    status = \"string\",\n    expirationTime = true,\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        if not aura_env.spell[spellIdS] and not aura_env.spellPhase[spellIdS] then\n            return false\n        end\n        \n        if aura_env.spell[spellIdS] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n                aura_env.antispam = GetTime()\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"isCasting\"\n                }\n                aura_env.ScheduleWarning(aura_env.castTime)\n                return true\n            end\n        end\n        \n        if aura_env.spellPhase[spellIdS] then\n            aura_env.phase = false\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n                status = \"onCD\"\n            }\n            return true\n        end\n        \n    end\n    \n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        \n        if extra and aura_env.msgPhaseShadow[extra] then\n            aura_env.count = 1\n            aura_env.phase = true\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdStart,\n                expirationTime = GetTime() + aura_env.cdStart,\n                progressType = \"timed\",\n                status = \"onCD\"\n            }\n            return true\n        end\n        \n        if extra and (aura_env.msgPhaseArcane[extra] or aura_env.msgPhaseNature[extra] or aura_env.msgPhaseFire[extra]) then\n            aura_env.phase = false\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n                status = \"onCD\"\n            }\n            return true\n        end\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id and aura_env.phase == true then\n            aura_env.count = aura_env.count + 1\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow - aura_env.castTime,\n                expirationTime = GetTime() + aura_env.cdWindow - aura_env.castTime,\n                progressType = \"timed\",\n                status = \"onCD\"\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 1\n        return true\n    end\nend",
