["custom"] = "function(allstates, event, extra, subEvent,_,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spellPhaseThree[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" then\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n            }\n            return true\n        end\n    end\n    \n    \n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        \n        if extra and aura_env.msgPhaseTwo[extra] then\n            aura_env.phaseOne = false\n            aura_env.text = \"Фаза 1\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.phaseTime,\n                expirationTime = GetTime() + aura_env.phaseTime,\n                progressType = \"timed\",\n            }\n            aura_env.ScheduleWarning(aura_env.phaseTime)\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseOne[extra] then\n            aura_env.phaseOne = true\n            aura_env.text = \"Фаза 2\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                progressType = \"timed\",\n            }\n            return true\n        end\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id and aura_env.phaseOne == false then\n            aura_env.phaseOne = true\n            aura_env.text = \"Фаза 2\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                progressType = \"timed\",\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.phaseOne = true\n        aura_env.text = \"Фаза 2\"\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart,\n            expirationTime = GetTime() + aura_env.cdStart,\n            progressType = \"timed\",\n        }\n        return true\n    end\nend",
