["customTextUpdate"] = "event",
["url"] = "https://wago.io/X2r68vxMW/64",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.npcIds = {\n    [\"63589\"] = true,\n}\n\nlocal marks = {\n    8,  -- Череп\n    7,  -- Крест\n    5,  -- Луна\n    4,  -- Трусы\n    3,  -- Ромб\n    6,  -- Квадрат\n}\nlocal index = 0\n\nfunction aura_env.getNextMark()\n    index = (index % #marks) + 1\n    return marks[index]\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "timed",
["events"] = "NAME_PLATE_UNIT_ADDED",
["spellIds"] = {
},
["subeventPrefix"] = "SPELL",
["names"] = {
},
["custom_type"] = "event",
["custom"] = "function(event, unit)\n    if event ~= \"NAME_PLATE_UNIT_ADDED\" or not unit or not UnitExists(unit) then\n        return false\n    end\n    \n    local npcId = select(6,strsplit(\"-\", UnitGUID(unit)))\n    if not aura_env.npcIds[npcId] then\n        return false\n    end\n    \n    local index = GetRaidTargetIndex(unit)\n    if index then\n        return false\n    end\n    \n    local mark = aura_env.getNextMark()\n    SetRaidTarget(unit, mark)\n    \n    return true\nend",
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
["activeTriggerMode"] = -10,
},
["displayText_format_p_time_mod_rate"] = true,
