["custom"] = "function(a, e, ...)\n    if e == \"OPTIONS\" then\n        a[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = math.random(1,100),\n            total = 100,\n            name = WeakAuras.myGUID\n        }\n        return true\n    end\n    \n    if e == \"WA_EMITY_TIMER\" then\n        local key, time, count, guid, name = ...\n        if key == \"UNSOK_AMBER_EXPLOSION_PLAYER_\" .. aura_env.key then\n            if time then\n                if time > 0 then\n                    if not a[name] then\n                        a[name] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"static\",\n                            value = 100,\n                            total = 100,\n                            name = guid\n                        }\n                        return true\n                    end\n                end\n            else\n                if a[name] then\n                    a[name].show = false\n                    a[name].changed = true\n                    return true\n                end\n            end\n        end\n    end\n    \n    if e == \"UNIT_POWER_UPDATE\" then\n        local unit = ...\n        local name = UnitName(unit)\n        \n        if a[name] then\n            a[name].value = UnitPower(unit, 10)\n            a[name].changed = true\n            return true\n        end\n    end\nend",
