["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"TRIGGER\" then\n        local triggerNum = extra\n        local triggerStates = subEvent\n        \n        if triggerNum == 2 then\n            for _, state in pairs(triggerStates) do\n                local haste = tonumber(state.tooltip1)\n                if haste then\n                    aura_env.hastePercent = haste\n                end\n            end\n        end\n        return true\n    end\n    \n    if event == \"WA_LEI_SCARY_FOG_REPEAT\" then\n        aura_env.scheduleRepeat()\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.getFogInterval(),\n            expirationTime = GetTime() + aura_env.getFogInterval(),\n            progressType = \"timed\",\n        }\n        return true\n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" or subEvent == \"SPELL_AURA_APPLIED_DOSE\" then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 2.5 then\n                aura_env.antispam = GetTime()\n                aura_env.scheduleRepeat()\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.getFogInterval(),\n                    expirationTime = GetTime() + aura_env.getFogInterval(),\n                    progressType = \"timed\",\n                }\n                return true\n            end\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart,\n            expirationTime = GetTime() + aura_env.cdStart,\n            progressType = \"timed\",\n        }\n        return true\n    end\nend",
