["custom_hide"] = "timed",
["customVariables"] = "{\n    expirationTime = true,\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS, sourceGUID,_,_,_,destGUID,_,_,_, spellId)\n    \n    if event == \"OPTIONS\" then\n        for i = 1,5 do\n            local dur = math.random(1, 60)\n            allstates[i] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = dur,\n                expirationTime = GetTime() + dur,\n                autoHide = true,\n                tar = WeakAuras.myGUID,\n                icon = C_Spell.GetSpellTexture(122224),\n            }\n        end\n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            local npcID = select(6, strsplit(\"-\", destGUID))\n            if aura_env.NPCs[npcID] then\n                allstates[destGUID] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.spell[spellId],\n                    expirationTime = GetTime() + aura_env.spell[spellId],\n                    progressType = \"timed\",\n                    tar = sourceGUID,\n                    icon = C_Spell.GetSpellTexture(spellId)\n                }\n                return true\n            end\n        end\n    end\n    \n    if subEvent == \"SPELL_AURA_APPLIED\" or subEvent == \"SPELL_AURA_REFRESH\" then\n        local npcID = select(6, strsplit(\"-\", destGUID))\n        if aura_env.NPCs[npcID] then\n            allstates[destGUID] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = aura_env.spell[spellId],\n                expirationTime = GetTime() + aura_env.spell[spellId],\n                progressType = \"timed\",\n                tar = sourceGUID,\n                icon = C_Spell.GetSpellTexture(spellId)\n            }\n            return true\n        end\n    end\n    \n    if subEvent == \"SPELL_AURA_REMOVED\" then\n        if allstates[destGUID] then\n            allstates[destGUID].show = false\n            allstates[destGUID].changed = true\n            return true\n        end\n    end\nend",
