["custom"] = "function(allstates, event, extra, subEvent, spellIdS, sourceGUID, sourceName,_,_,_,_,_,_, spellId)\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = 10,\n            expirationTime = GetTime() + 10,\n            progressType = \"timed\",\n            autoHide = true,\n            icon = 651090,\n            status = \"Prewarn\",\n        }\n        return true \n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if subEvent == \"SWING_DAMAGE\" or subEvent == \"SWING_MISSED\" then\n            if sourceName == \"Ша Страха\" then\n                if not aura_env.antispam or GetTime() - aura_env.antispam > 2 then\n                    aura_env.count = aura_env.count - 1\n                    \n                    if aura_env.count < 0 then\n                        aura_env.count = 0\n                    end\n                    \n                    if aura_env.buffCount == 3 then\n                        allstates[\"\"] = {\n                            show = true,\n                            changed = true,\n                            duration = 2.5,\n                            expirationTime = GetTime() + 2.5,\n                            progressType = \"timed\",\n                            autoHide = false,\n                            icon = 425957,\n                        }\n                        return true\n                    else\n                        allstates[\"\"] = {\n                            show = true,\n                            changed = true,\n                            duration = 2.5,\n                            expirationTime = GetTime() + 2.5,\n                            progressType = \"timed\",\n                            autoHide = false,\n                            icon = 651090,\n                        }\n                        return true\n                    end\n                end\n            end\n        end\n        \n        if not aura_env.spellBuffOne[spellId] and not aura_env.spellBuffTwo[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and aura_env.spellBuffOne[spellId] then\n            aura_env.count = 0\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = 2.5,\n                expirationTime = GetTime() + 2.5,\n                progressType = \"timed\",\n                autoHide = false,\n                icon = 651090,\n                status = \"Prewarn\",\n            }\n            return true\n        end\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and aura_env.spellBuffOne[spellId] then\n            if aura_env.phaseOne == true then\n                aura_env.antispam = GetTime()\n                aura_env.count = 3\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = 2.5,\n                    expirationTime = GetTime() + 2.5,\n                    progressType = \"timed\",\n                    autoHide = false,\n                    icon = 651090,\n                    status = \"Normal\",\n                }\n                return true\n            else\n                aura_env.buffCount = aura_env.buffCount + 1\n                if aura_env.buffCount == 3 then\n                    aura_env.antispam = GetTime()\n                    aura_env.count = 3\n                    allstates[\"\"] = {\n                        show = true,\n                        changed = true,\n                        duration = 2.5,\n                        expirationTime = GetTime() + 2.5,\n                        progressType = \"timed\",\n                        autoHide = false,\n                        icon = 425957,\n                        status = \"Normal\",\n                    }\n                else\n                    aura_env.antispam = GetTime()\n                    aura_env.count = 3\n                    allstates[\"\"] = {\n                        show = true,\n                        changed = true,\n                        duration = 2.5,\n                        expirationTime = GetTime() + 2.5,\n                        progressType = \"timed\",\n                        autoHide = false,\n                        icon = 651090,\n                        status = \"Normal\",\n                    }\n                    return true\n                end\n            end\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and aura_env.spellBuffTwo[spellId] then\n            aura_env.count = 0\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = 2.5,\n                expirationTime = GetTime() + 2.5,\n                progressType = \"timed\",\n                autoHide = false,\n                icon = 425957,\n                status = \"Prewarn\",\n            }\n            return true\n        end\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and aura_env.spellBuffTwo[spellId] then\n            aura_env.antispam = GetTime()\n            aura_env.count = 3\n            aura_env.buffCount = 0\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = 2.5,\n                expirationTime = GetTime() + 2.5,\n                progressType = \"timed\",\n                autoHide = false,\n                icon = 651090,\n                status = \"Normal\",\n            }\n            return true\n        end\n    end\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        if not aura_env.spellPhase[spellIdS] then\n            return false\n        end\n        aura_env.phaseOne = false\n        aura_env.count = 3\n        aura_env.buffCount = 0\n        return true\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 3\n        aura_env.phaseOne = true\n        aura_env.buffCount = 0\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = 2.5,\n            expirationTime = GetTime() + 2.5,\n            progressType = \"timed\",\n            autoHide = false,\n            icon = 651090,\n            status = \"Normal\",\n        }\n        return true\n    end\nend",
