["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS, sourceGUID,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            icon = 461120,\n        }\n        return true \n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        local npcID = select(6, strsplit(\"-\", sourceGUID))\n        if aura_env.NPCs[npcID] then\n            if subEvent == \"SPELL_CAST_START\" then\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.precastTime,\n                    expirationTime = GetTime() + aura_env.precastTime,\n                    progressType = \"timed\",\n                    icon = 461120,\n                    status = \"precast\"\n                }\n                return true\n            end\n            \n            if subEvent == \"SPELL_CAST_SUCCESS\" then\n                if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n                    aura_env.antispam = GetTime()\n                    allstates[\"\"] = {\n                        show = true,\n                        changed = true,\n                        autoHide = true,\n                        duration = aura_env.castTime,\n                        expirationTime = GetTime() + aura_env.castTime,\n                        progressType = \"timed\",\n                        icon = 461120,\n                        status = \"cast\"\n                    }\n                    return true\n                end\n            end\n        end\n    end\n    \n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        if not aura_env.spellPhase[spellIdS] then\n            return false\n        end\n        allstates[\"\"] = {\n            show = false,\n            changed = true,\n        }\n        return true\n    end\nend",
