["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, extra)\n    if event == \"CHAT_MSG_MONSTER_YELL\" then\n        if extra and aura_env.msgPhaseArcane[extra] then\n            aura_env.text = \"ЧАРОДЕЙСКАЯ ФАЗА\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\Spread.mp3\", \"Master\")\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseFire[extra] then\n            aura_env.text = \"ОГНЕННАЯ ФАЗА\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            PlaySoundFile(\"Interface\\\\AddOns\\\\EmityCore\\\\sound\\\\MaloriakRedPhase.mp3\", \"Master\")\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseNature[extra] then\n            aura_env.text = \"ГРОЗОВАЯ ФАЗА\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            return true\n        end\n        \n        if extra and aura_env.msgPhaseShadow[extra] then\n            aura_env.text = \"ТЕМНАЯ ФАЗА\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = 2,\n                progressType = \"timed\",\n            }\n            return true\n        end\n    end\nend",
