["customText"] = "function()\n    local multi = 102015 -- 25 гер\n    local _, _, difficultyID = GetInstanceInfo()\n    -- 3 = 10 Нормал; 4 = 25 Нормал; 5 = 10 Героик; 6 = 25 Героик\n    if difficultyID == 3 then\n        multi =  45000\n    elseif difficultyID == 4 then\n        multi = 59985\n    elseif difficultyID == 5 then\n        multi = 76500\n    end\n    local colorCode = \"|cFFfff468\"\n    return colorCode .. math.floor(multi / 1000) .. \"k/с|r\"\nend\n\n\n\n",
