["iconSource"] = 0,
["wagoID"] = "X2r68vxMW",
["authorOptions"] = {
},
["adjustedMax"] = "",
["customText"] = "function()\n    local colorCode = \"|cFFfff468\"\n    return colorCode .. aura_env.count .. \"|r\"\nend\n\n\n",
