["do_sound"] = true,
},
["init"] = {
["custom"] = "aura_env.spell = {\n    [125310] = 0,\n}\naura_env.spellPhase = {\n    [130908] = 0,\n}\naura_env.count = 1\naura_env.precastTime = 3\naura_env.castTime = 6",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "aura_env.count = aura_env.count + 1",
["do_custom"] = true,
