},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_hide"] = "timed",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    status = \"string\",\n    expirationTime = true,\n}",
["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        if aura_env.spellPhase[spellIdS] then\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n            }\n            return true\n        end\n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = false,\n                duration = aura_env.precastTime,\n                expirationTime = GetTime() + aura_env.precastTime,\n                progressType = \"timed\",\n                status = \"precast\"\n            }\n            return true\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = true,\n                duration = aura_env.castTime,\n                expirationTime = GetTime() + aura_env.castTime,\n                progressType = \"timed\",\n                status = \"cast\"\n            }\n            return true\n            \n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 1\n        return true\n    end\nend",
["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_SUCCESS, CLEU:SPELL_CAST_START, UNIT_SPELLCAST_SUCCEEDED",
