["custom"] = "function(a, e, ...)\n    if e == \"OPTIONS\" then\n        local health = math.random(1,300000)\n        local maxHealth = 300000\n        a[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = health,\n            total = maxHealth,\n            percent = math.floor(0.5 + (health / math.max(1, maxHealth)) * 100),\n            name = WeakAuras.myGUID\n        }\n        return true\n    end\n    \n    if e == \"WA_EMITY_TIMER\" then\n        local key, time, count, guid, name = ...\n        if key == \"UNSOK_AMBER_EXPLOSION_PLAYER_\" .. aura_env.key then\n            if time then\n                if time > 0 then\n                    local health = UnitHealth(name) or 1\n                    local maxHealth = UnitHealthMax(name) or 1\n                    if not a[name] then\n                        a[name] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"static\",\n                            value = health,\n                            total = maxHealth,\n                            percent = math.floor(0.5 + (health / math.max(1, maxHealth)) * 100),\n                            name = guid\n                        }\n                        return true\n                    end\n                end\n            else\n                if a[name] then\n                    a[name].show = false\n                    a[name].changed = true\n                    return true\n                end\n            end\n        end\n    end\n    \n    if e == \"UNIT_HEALTH\" then\n        local unit = ...\n        local name = UnitName(unit)\n        \n        if a[name] then\n            local health = UnitHealth(unit) or 1\n            local maxHealth = UnitHealthMax(unit) or 1\n            a[name].value = health\n            a[name].total = maxHealth\n            a[name].percent = math.floor(0.5 + (health / math.max(1, maxHealth)) * 100)\n            a[name].changed = true\n            return true\n        end\n    end\nend",
