["check"] = "event",
["custom_type"] = "stateupdate",
["custom"] = "function(allstates,event,guid,subEvent,_,sourceGUID,_,_,_,destGUID,destName,_,_,spellId)\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        if not aura_env.spellPhase[spellIdS] then\n            return false\n        end\n        \n        if allstates[\"\"] then\n            allstates[\"\"].show = false\n            allstates[\"\"].changed = true\n        end\n        return true\n    end\n    \n    if (subEvent == \"SPELL_DAMAGE\" or subEvent == \"SPELL_MISSED\") and spellId == aura_env.spellId then\n        if not aura_env.guids[sourceGUID] then\n            aura_env.guids[sourceGUID] = true\n            if allstates[\"\"] then\n                allstates[\"\"].value = allstates[\"\"].value + 1\n                allstates[\"\"].changed = true\n            else\n                allstates[\"\"] = {\n                    progressType = \"static\",\n                    value = 1,\n                    show = true,\n                    changed = true,\n                }\n            end\n            return true\n        end\n    end\n    \n    if subEvent == \"UNIT_DIED\" then\n        local npcId = select(6, strsplit(\"-\", destGUID))\n        if npcId == \"61034\" then\n            if allstates[\"\"] and allstates[\"\"].value > 0 then\n                allstates[\"\"].value = allstates[\"\"].value - 1\n                allstates[\"\"].changed = true\n                if allstates[\"\"].value == 0 then\n                    allstates[\"\"].show = false\n                    allstates[\"\"].changed = true\n                end\n                return true\n            end\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        wipe(aura_env.guids)\n    end\n    return false\nend",
