["custom"] = "aura_env.spell = {\n    [122415] = 0,\n}\naura_env.spellPhase = {\n    [122540] = 0,\n}\naura_env.NPCs = {\n    [\"62711\"] = true,\n}\naura_env.phaseThree = false\naura_env.count = 1\naura_env.cdStart = 30.5\naura_env.cdWindow = 31\naura_env.castTime = 1.5\n\naura_env.ScheduleWarning = function(timer)\n    if aura_env.scheduledTimer then WeakAuras.timer:CancelTimer(aura_env.scheduledTimer) end\n    aura_env.scheduledTimer = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, timer, 'SCHEDULED_WARNING', aura_env.id)\nend",
