["remOperator"] = "<=",
["event"] = "Health",
["useName"] = true,
["events"] = "CHAT_MSG_MONSTER_YELL, CLEU:SPELL_AURA_APPLIED, CLEU:SPELL_AURA_REFRESH",
["custom"] = "function(a, e, extra, subEvent, _, sourceGUID, _, _, _, destGUID, destName, _, _, spellId)\n    if e == \"OPTIONS\" then\n        for i = 1, 3 do\n            a[i] = {\n                show = true,\n                changed = true,\n                name = WeakAuras.me,\n                amount = math.random(1, 4)\n            }\n        end\n        return true\n    end\n    \n    if e == \"CHAT_MSG_MONSTER_YELL\" then\n        if extra and (extra == aura_env.msgNightVar1 or extra == aura_env.msgNightVar2 or extra == aura_env.msgNightVar3) then\n            aura_env.allow = false\n            \n            for _, state in pairs(a) do\n                state.show = false\n                state.changed = true\n            end\n            return true\n        end\n        if extra and (extra == aura_env.msgDayVar1 or extra == aura_env.msgDayVar2 or extra == aura_env.msgDayVar3) then\n            aura_env.allow = true\n            aura_env.complete = false\n            aura_env.counts = {}\n            return true\n        end\n    end\n    \n    if not aura_env.allow or aura_env.complete then\n        return\n    end\n    \n    if spellId ~= aura_env.spellID then\n        return false\n    end\n    \n    if (subEvent == \"SPELL_AURA_APPLIED\" or subEvent == \"SPELL_AURA_REFRESH\") then\n        \n        aura_env.counts[destName] = (aura_env.counts[destName] or 0) + 1\n        \n        a[destName] = {\n            show = true,\n            changed = true,\n            name = destName,\n            amount = aura_env.counts[destName],\n        }\n        return true\n    end\nend",
