["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent,_,_,_,_,_, destGUID,_,_,_, spellId)\n    \n    if event == \"EMITY_ABOM_START\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart,\n            expirationTime = GetTime() + aura_env.cdStart,\n            progressType = \"timed\",\n            status = \"onCD\"\n        }\n        return true\n    end\n    \n    if event == \"EMITY_ABOM_CAST\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.castTime,\n            expirationTime = GetTime() + aura_env.castTime,\n            progressType = \"timed\",\n            status = \"isCasting\"\n        }\n        aura_env.ScheduleWarning(aura_env.castTime)\n        return true\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow - aura_env.castTime,\n                expirationTime = GetTime() + aura_env.cdWindow - aura_env.castTime,\n                progressType = \"timed\",\n                status = \"onCD\"\n            }\n            return true\n        end\n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and destGUID == WeakAuras.myGUID then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow,\n                expirationTime = GetTime() + aura_env.cdWindow,\n                progressType = \"timed\",\n                status = \"onCD\"\n            }\n            return true\n        end\n    end\nend",
