["init"] = {
["custom"] = "aura_env.spell = {\n    [123705] = 0,\n}\naura_env.count = 1\naura_env.cdStart = 10\naura_env.cdWindow = 10\naura_env.hastePercent = 0\n\nfunction aura_env.getFogInterval()\n    local baseInterval = aura_env.cdWindow\n    local haste = aura_env.hastePercent or 0\n    local interval = baseInterval / (1 + haste / 100)\n    \n    return interval\nend\n\nfunction aura_env.scheduleRepeat()\n    if aura_env.timer then\n        aura_env.timer:Cancel()\n        aura_env.timer = nil\n    end\n    local interval = aura_env.getFogInterval()\n    aura_env.timer = C_Timer.NewTimer(interval, function()\n            WeakAuras.ScanEvents(\"WA_LEI_SCARY_FOG_REPEAT\")\n    end)\nend",
