["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] and not aura_env.spellPhaseOne[spellId] and not aura_env.spellPhase[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spell[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n                aura_env.antispam = GetTime()\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"isCasting\"\n                }\n                aura_env.ScheduleWarning(aura_env.castTime)\n                return true\n            end\n        end\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and aura_env.spellPhaseOne[spellId] then\n            aura_env.conduitCount = aura_env.conduitCount + 1\n            if aura_env.conduitCount == 6 then\n                aura_env.count = 1\n                aura_env.conduitCount = 1\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.cdStartAfterPhase,\n                    expirationTime = GetTime() + aura_env.cdStartAfterPhase,\n                    progressType = \"timed\",\n                    status = \"onCD\"\n                }\n            end\n            return true\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spellPhase[spellId] then\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n            }\n            return true\n        end\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id then\n            aura_env.count = aura_env.count + 1\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdWindow - aura_env.castTime,\n                expirationTime = GetTime() + aura_env.cdWindow - aura_env.castTime,\n                progressType = \"timed\",\n                status = \"onCD\"\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 1\n        aura_env.conduitCount = 1\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart,\n            expirationTime = GetTime() + aura_env.cdStart,\n            progressType = \"timed\",\n            status = \"onCD\"\n        }\n        return true\n    end\nend",
