["custom"] = "function(allstates, event, ...)\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            tar = UnitGUID(\"player\"),\n        }\n    end\n    \n    if event == \"EMITY_EYE\" then\n        local sourceGUID = ...\n        allstates[sourceGUID] = {\n            show = true,\n            changed = true,\n            duration = 3,\n            expirationTime = 3 + GetTime(),\n            progressType = \"timed\",\n            tar = nil,\n            autoHide = true,\n        }\n        return true\n    end\n    \n    if event == \"EMITY_EYE_TARGET\" then\n        local sourceGUID, destGUID = ...\n        for guid, state in pairs(allstates) do\n            if guid == sourceGUID then\n                state.tar = destGUID\n                state.changed = true\n            end\n        end\n        return true\n    end\n    \n    \n    \nend",
