["wagoID"] = "X2r68vxMW",
["authorOptions"] = {
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "\n\n",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/X2r68vxMW/64",
["actions"] = {
["start"] = {
["sound"] = "Interface\\Addons\\EmityCore\\sound\\BreathSoon.mp3",
["do_sound"] = true,
},
["init"] = {
["custom"] = "aura_env.spell = {\n    [117960] = 0,\n}\naura_env.spellPhase = {\n    [124967] = 0,\n}\naura_env.spellPhaseOne = {\n    [116598] = 0,\n}\naura_env.count = 1\naura_env.cdStart = 7\naura_env.cdStartAfterPhase = 16.5\naura_env.cdWindow = 17\n\naura_env.ScheduleWarning = function(timer)\n    if aura_env.scheduledTimer then WeakAuras.timer:CancelTimer(aura_env.scheduledTimer) end\n    aura_env.scheduledTimer = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, timer - 4, 'SCHEDULED_WARNING', aura_env.id)\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_hide"] = "timed",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    expirationTime = true,\n}",
["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, extra, subEvent,_,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            icon = \"Interface\\\\Icons\\\\spell_fire_blueflamebreath\",\n            count = math.random(1,3)\n        }\n        return true \n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] and not aura_env.spellPhase[spellId] and not aura_env.spellPhaseOne[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spell[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n                aura_env.antispam = GetTime()\n                aura_env.count = aura_env.count + 1\n                aura_env.ScheduleWarning(aura_env.cdWindow)\n                allstates[\"\"] = {\n                    show = false,\n                    changed = true,\n                }\n                return true\n            end\n        end\n        \n        if subEvent == \"SPELL_AURA_REMOVED\" and aura_env.spellPhaseOne[spellId] then\n            aura_env.conduitCount = aura_env.conduitCount + 1\n            if aura_env.conduitCount == 6 then\n                aura_env.count = 1\n                aura_env.conduitCount = 1\n                aura_env.phaseOne = true\n                aura_env.ScheduleWarning(aura_env.cdStartAfterPhase)\n            end\n            return true\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spellPhase[spellId] then\n            aura_env.phaseOne = false\n            allstates[\"\"] = {\n                show = false,\n                changed = true,\n            }\n            return true\n        end\n        \n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id and aura_env.phaseOne == true then\n            aura_env.customText = \"ДЫХАНИЕ\"\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = 4,\n                expirationTime = GetTime() + 4,\n                progressType = \"timed\",\n                icon = \"Interface\\\\Icons\\\\spell_fire_blueflamebreath\",\n                count = aura_env.count,\n            }\n            return true\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.phaseOne = true\n        aura_env.count = 1\n        aura_env.conduitCount = 1\n        aura_env.ScheduleWarning(aura_env.cdStart)\n        return true\n    end\nend",
["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_START, SCHEDULED_WARNING, CLEU:SPELL_CAST_SUCCESS, CLEU:SPELL_AURA_REMOVED",
