["custom_type"] = "stateupdate",
["customVariables"] = "{\n    level = \"string\",\n    desc = \"string\",\n    receiver = \"string\",\n    glow = \"bool\",\n    legenadry = \"bool\"\n}",
["event"] = "Health",
["unit"] = "player",
