},
["init"] = {
["custom"] = "local bossID = 60399\n\nlocal GetGUIDCreatureID = function(GUID)\n    local guidType, _, id1, _, _, id2 = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id2) or 0\n    elseif guidType == \"Player\" or guidType == \"Item\" then\n        return tonumber(id1) or 0\n    end\n    return 0\nend\n\naura_env.CheckNpcID = function(unitID)\n    local unitGUID = UnitExists(unitID) and UnitGUID(unitID)\n    \n    if unitGUID then\n        local npcID = GetGUIDCreatureID(unitGUID)\n        return npcID == bossID\n    end\nend",
["do_custom"] = true,
