["event"] = "Health",
["use_unit"] = true,
["custom"] = "function(states, e, unitID)\n    if e == 'UNIT_POWER_FREQUENT' and aura_env.CheckNpcID(unitID) then\n        local curPower = UnitPower(unitID)\n        local prevPower = aura_env.prevPower\n        \n        if prevPower then\n            if curPower > prevPower then\n                if not states[''] then\n                    states:Update('', {})\n                end\n            elseif curPower < prevPower then\n                states:Remove('')\n            end\n        end\n        \n        aura_env.prevPower = curPower\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.prevPower = 0\n    end\nend",
