["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates, event, extra, subEvent,_,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spell[spellId] and not aura_env.spellPrecast[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spellPrecast[spellId] then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                autoHide = false,\n                duration = aura_env.precastTime,\n                expirationTime = GetTime() + aura_env.precastTime,\n                progressType = \"timed\",\n                status = \"precast\"\n            }\n            return true\n        end\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spell[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 8.5 then\n                aura_env.antispam = GetTime()\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    duration = aura_env.castTime,\n                    expirationTime = GetTime() + aura_env.castTime,\n                    progressType = \"timed\",\n                    status = \"cast\"\n                }\n                return true\n            end\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 1\n        return true\n    end\nend",
