["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["custom"] = "function(allstates,event,_,subEvent,_,sourceGUID,_,_,_,destGUID,destName,_,_,spellId,_,_,_,amount)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            icon = \"Interface\\\\Icons\\\\ability_warlock_shadowflame\",\n            stacks = math.random(1,3),\n            name = UnitName(\"player\")\n        }\n    end\n    \n    if spellId ~= 122752 then\n        return false\n    end\n    \n    if subEvent == \"SPELL_AURA_APPLIED\" then\n        allstates[destGUID] = {\n            show = true,\n            changed = true,\n            duration = 3.5,\n            expirationTime = GetTime() + 2.5,\n            progressType = \"timed\",\n            icon = \"Interface\\\\Icons\\\\ability_warlock_shadowflame\",\n            autoHide = true,\n            stacks = 1,\n            name = destName\n        }\n        return true\n    elseif subEvent == \"SPELL_AURA_APPLIED_DOSE\" then\n        allstates[destGUID] = {\n            show = true,\n            changed = true,\n            duration = 3.5,\n            expirationTime = GetTime() + 2.5,\n            progressType = \"timed\",\n            icon = \"Interface\\\\Icons\\\\ability_warlock_shadowflame\",\n            autoHide = true,\n            stacks = amount,\n            name = destName\n        }\n        return true\n    end\nend",
