["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"RAID_BOSS_EMOTE\" then\n        \n        if extra and aura_env.msgAdds[extra] then\n            aura_env.ScheduleWarning(aura_env.castTime)\n            return true\n        end\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id then\n            aura_env.count = aura_env.count + 1\n            if aura_env.count >= 3 then\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.cdWindowDelayed,\n                    expirationTime = GetTime() + aura_env.cdWindowDelayed,\n                    progressType = \"timed\",\n                }\n                return true\n            else\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.cdWindow,\n                    expirationTime = GetTime() + aura_env.cdWindow,\n                    progressType = \"timed\",\n                }\n                return true\n            end\n        end\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.count = 1\n        local  _, _, difficultyID = GetInstanceInfo()\n        if difficultyID == 5 or difficultyID == 6 then\n            aura_env.cdStart = 58.5\n        else\n            aura_env.cdStart = 60\n        end\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            duration = aura_env.cdStart + aura_env.castTime,\n            expirationTime = GetTime() + aura_env.cdStart + aura_env.castTime,\n            progressType = \"timed\",\n        }\n        return true\n    end\nend",
