["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, extra, subEvent, spellIdS,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        if not aura_env.spellSubmerge[spellId] and not aura_env.spellImplaceable[spellId] and not aura_env.spellHuddle[spellId] and not aura_env.spellWaterspout[spellId] then\n            return false\n        end\n        \n        if subEvent == \"SPELL_AURA_APPLIED\" and aura_env.spellHuddle[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 4 then\n                aura_env.antispam = GetTime()\n                aura_env.count = aura_env.count + 1\n                if aura_env.count <= 3 then\n                    allstates[\"\"] = {\n                        show = true,\n                        changed = true,\n                        duration = aura_env.cdWindow,\n                        expirationTime = GetTime() + aura_env.cdWindow,\n                        progressType = \"timed\",\n                        status = \"onCD\"\n                    }\n                    return true\n                else\n                    allstates[\"\"] = {\n                        show = false,\n                        changed = true,\n                        status = \"onCD\"\n                    }\n                    return true\n                end\n            end\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spellWaterspout[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 4 then\n                aura_env.antispam = GetTime()\n                aura_env.count = aura_env.count + 1\n                if aura_env.count <= 3 then\n                    allstates[\"\"] = {\n                        show = true,\n                        changed = true,\n                        duration = aura_env.cdWindow,\n                        expirationTime = GetTime() + aura_env.cdWindow,\n                        progressType = \"timed\",\n                        status = \"onCD\"\n                    }\n                    return true\n                else\n                    allstates[\"\"] = {\n                        show = false,\n                        changed = true,\n                        status = \"onCD\"\n                    }\n                    return true\n                end\n            end\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spellImplaceable[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 4 then\n                aura_env.antispam = GetTime()\n                aura_env.count = aura_env.count + 1\n                if aura_env.count <= 3 then\n                    allstates[\"\"] = {\n                        show = true,\n                        changed = true,\n                        duration = aura_env.cdWindow,\n                        expirationTime = GetTime() + aura_env.cdWindow,\n                        progressType = \"timed\",\n                        status = \"onCD\"\n                    }\n                    return true\n                else\n                    allstates[\"\"] = {\n                        show = false,\n                        changed = true,\n                        status = \"onCD\"\n                    }\n                    return true\n                end\n            end\n        end\n        \n        if subEvent == \"SPELL_CAST_START\" and aura_env.spellSubmerge[spellId] then\n            if not aura_env.antispam or GetTime() - aura_env.antispam > 4 then\n                aura_env.antispam = GetTime()\n                aura_env.count = 1\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    duration = aura_env.cdStart,\n                    expirationTime = GetTime() + aura_env.cdStart,\n                    progressType = \"timed\",\n                    status = \"onCD\"\n                }\n                return true\n            end\n        end\n    end\n    \n    if event == 'SCHEDULED_WARNING' then\n        if extra == aura_env.id then\n            aura_env.count = 1\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                duration = aura_env.cdStart,\n                expirationTime = GetTime() + aura_env.cdStart,\n                progressType = \"timed\",\n                status = \"onCD\"\n            }\n            return true\n        end\n    end\nend",
