["events"] = "CHAT_MSG_RAID, CHAT_MSG_RAID_LEADER, CHAT_MSG_RAID_WARNING, LOOT_ITEM_AVAILABLE, CHAT_MSG_LOOT, START_LOOT_ROLL",
["names"] = {
},
["check"] = "event",
["spellIds"] = {
},
["custom"] = "function(allstates, event, text, extra)\n    \n    if not text then \n        return false\n    end\n    \n    for _,v in pairs(aura_env.config.items) do\n        local finditem = \"Hitem:\"..v.item_id..\":\"\n        local bonusText = \"дополнительную\"\n        if string.find(text, finditem, 1, true) and not string.find(text, bonusText, 1, true) then\n            local itemName, _, itemRarity, itemLevel, _, _, itemSubType, _, _, itemIcon = C_Item.GetItemInfo(v.item_id)\n            if itemName == nil then\n                itemName = v.item_name\n            end\n            local legenadryItem = false\n            local description = \"\"\n            local player = \"\"\n            local firstItem = true\n            \n            if aura_env.slot[v.slotItem] then\n                description = aura_env.slot[v.slotItem]\n            end\n            \n            if aura_env.armor[itemSubType] then\n                description = description .. \", \" .. aura_env.armor[itemSubType]\n            end\n            \n            if aura_env.boe[v.item_id] then\n                description = description .. \", БоЕ\"\n            end\n            \n            if itemRarity == 5 then \n                legenadryItem = true\n            end\n            \n            if v.slotItem <= 29 then\n                for i = 1, 31 do\n                    local specName = aura_env.spec[i]\n                    local table = v.specBis\n                    if table[specName] then\n                        if firstItem == true then\n                            description = description .. \" - Бис \" .. aura_env.specText[i]\n                            firstItem = false\n                        else\n                            description = description .. \", \" .. aura_env.specText[i]\n                        end\n                    end\n                end\n            end\n            \n            allstates[v.item_id] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                expirationTime = GetTime() + 30,\n                duration = 30,\n                name = itemName,\n                icon = itemIcon,\n                autoHide = true,\n                itemId = v.item_id,\n                desc = description,\n                level = itemLevel,\n                glow = v.bisItem,\n                legenadry = legenadryItem,\n                receiver = player\n            }\n            return true\n        end\n    end\nend",
["debuffType"] = "HELPFUL",
},
