["custom"] = "function(a, e, ...)\n    if e == \"OPTIONS\" then\n        a[\"\"] = {\n            show = true,\n            changed = true,\n            total = 30,\n            value = 13,\n            progressType = \"static\",\n        }\n        return true\n    end\n    \n    if e == \"WA_GARALON_RANGE_CHECK\" then\n        for _, state in pairs(a) do\n            state.show = false\n            state.changed = true\n        end\n        \n        local rangeValue = nil\n        for i = 1, 5 do\n            local unit = \"boss\" .. i\n            if UnitExists(unit) and select(6, strsplit(\"-\", UnitGUID(unit))) == \"63191\" then\n                local minRange, maxRange = WeakAuras.GetRange(unit)\n                rangeValue = minRange\n                break\n            end\n        end\n\n        if rangeValue then\n            a[\"\"] = {\n                show = true,\n                changed = true,\n                total = 30,\n                value = rangeValue,\n                progressType = \"static\",\n            }\n            return true\n        end\n    end\nend",
